      cctv: [
        { id: 'B.c1', type: 'write', prompt: 'Write in Korean: “Yesterday, it rained. Nevertheless, we played soccer.” (축구를 하다 = to play soccer)', ans: ['어제는 비가 왔어요. 그래도 축구를 했어요.'], soft: [{ p: '어제(는|) 비가 왔어요 그래도 축구(를|) 했어요', note: 'Accepted.' }], skill: 'l12.usage', diag: [{ p: '어제(는|) 비가 와요 그래도 축구(를|) 했어요', note: 'Yesterday → past: 비가 왔어요.' }, { p: '어제(는|) 비가 왔어요 그래서 축구(를|) 했어요', note: '그래서 = so. → 그래도.' }], explain: 'Textbook sample sentence.', en: 'Yesterday, it rained. Nevertheless, we played soccer.' },
        { id: 'B.c2', type: 'mc', prompt: '“But still, don’t worry.”', opts: ['그래도 걱정하지 마세요.', '그래서 걱정하지 마세요.', '그래도 걱정해요.', '그래도 걱정하지 마요세요.'], skill: 'l12.form', explain: 'Textbook: 저도 돈이 없어요. 그래도 걱정하지 마세요.', en: 'But still, don’t worry.' },
        { id: 'B.c3', type: 'write', prompt: 'Write in Korean: “I’m busy these days. But I’m still studying Korean.”', ans: ['요즘 바빠요. 그래도 한국어를 공부하고 있어요.'], soft: [{ p: '요즘(에|) 바빠요 그래도 한국어(를|) 공부하고 있어요', note: 'Accepted.' }, { p: '요즘(에|) 바빠요 그래도 한국어(를|) 공부해요', note: 'Accepted. The book: 공부하고 있어요 (am studying).' }], skill: 'l12.form', diag: [{ p: '요즘 바뻐요 그래도 한국어를 공부하고 있어요', note: '바쁘다 → 바빠요.' }], explain: 'Textbook sample sentence.', en: 'I’m busy these days. But I’m still studying Korean.' },
        { id: 'B.c4', type: 'fill', prompt: 'Workbook 11: “It’s too hot. But still, I like summer more than winter.”', ko: '너무 더워요. ___ 저는 겨울보다 여름이 더 좋아요.', ans: ['그래도'], units: ['그', '래', '도'], extra: ['서', '두', '요'], skill: 'l12.usage', explain: 'Workbook 11 example answer. 보다 = than, 더 = more.', en: 'It’s too hot. But still, I like summer more than winter.' },
        { id: 'B.c5', type: 'enOpts', prompt: '“일이 늦게 끝날 거예요. 그래도 기다려 줄 수 있어요?” (workbook dictation)', opts: ['I will get off work late. Nevertheless, can you still wait for me?', 'Work ends late, so I can’t wait.', 'Work ended late. Did you wait?', 'I will finish early. Can you wait?'], skill: 'l12.usage', explain: 'Workbook 17.', en: 'I will get off work late. Nevertheless, can you still wait for me?' },
        { id: 'B.c6', type: 'mc', prompt: 'Which spelling is right?', opts: ['그래도요', '그래두요', '글애도요', '그레도요'], skill: 'l12.form', explain: 'Many people say 그래두요, but it is written 그래도요.', en: '' },
      ],
