          q: { type: 'enOpts', prompt: 'What does Grandma want?', opts: ['To eat ramen, even without her wallet.', 'To go back upstairs for her wallet.', 'To buy a new wallet.', 'To pay for the ramen with her card.'], skill: 'l12.usage',
            explain: '지갑이 없어요 (no wallet) + 그래도 + 먹고 싶어요 (still want to eat).', en: 'I don’t have my wallet. But I still want to eat ramen.' },
