MM.mnemo[12] = {"cards":[{"id":"ko-k3-0238","w":"그래도","cs":"přesto; i tak; nicméně","en":"but still; nevertheless","p":"o","o":"k","ex":"비가 와요. 그래도 갈 거예요?","exc":"Prší. I tak tam půjdeš? (가 → 1. pád; -ㄹ 거예요 → půjdeš)","h":"KŮ-RE-DO ≈ KUŘE DO: je pozdě, přesto dám kuře do trouby.","m":"Spojka vzniklá ze slovesa 그렇다 (být takový) + přípona -아도/-어도 (i když) = ‚i když je to tak, přesto‘."},{"id":"ko-k3-0239","w":"축구","cs":"fotbal; kopaná","en":"soccer","p":"n","o":"s","ex":"어제는 비가 왔어요. 그래도 축구를 했어요.","exc":"Včera pršelo. Přesto jsme hráli fotbal. (는 → téma; 가 → 1. pád; 를 → 4. pád)","h":"ČUK-KU ≈ ČUK! KUK!: čuk do míče – a kuk, gól.","m":"蹴 kopat + 球 míč, koule = kopaná, tedy fotbal. 球 jako v 야구 (baseball) nebo 농구 (basketbal).","hada":1,"r":["chuk-蹴","gu-球"]},{"id":"ko-k3-0240","w":"걱정하다","cs":"dělat si starosti; obávat se; strachovat se","en":"to worry","p":"v","o":"k","ex":"저도 돈이 없어요. 그래도 걱정하지 마세요.","exc":"Já také nemám peníze. Přesto si nedělejte starosti. (도 → také, i; 이 → 1. pád; -지 마세요 → nedělejte)","h":"KOK-ČONG ≈ KOKTÁ: ze samých starostí koktá.","m":"Základ 걱정 (starost, obava) + 하다 (dělat). Častá fráze pro uklidnění: 걱정하지 마세요 = Nedělejte si starosti / Nebojte se.","tv":["걱정해요","걱정했어요","걱정할 거예요"]},{"id":"ko-k3-0241","w":"노래방","cs":"karaoke pokoj; zpívárna","en":"noraebang (singing room)","p":"n","o":"m","ex":"노래방에 가야 돼요. 그래도 노래 안 할 거예요.","exc":"Musím jít do karaoke pokoje. Ale zpívat nebudu. (에 → kam; -아야 돼요 → muset)","h":"노래 = píseň (NO-RE ≈ NORA) + 방 = pokoj: pokoj na zpívání.","m":"Složené z 노래 (píseň) + 房 (pokoj, místnost) = soukromý pokoj na zpívání karaoke, populární v Koreji. 房 jako v PC방 (internetová herna).","r":["bang-房"]},{"id":"ko-k3-0242","w":"노래하다","cs":"zpívat","en":"to sing","p":"v","o":"k","ex":"노래방에 가야 돼요. 그래도 노래 안 할 거예요.","exc":"Musím jít do karaoke pokoje. Ale zpívat nebudu. (에 → kam; -아야 돼요 → muset)","h":"NO-RE ≈ NORA: liška si v noře zpívá.","m":"Základ 노래 (píseň) + 하다 (dělat) = zpívat. Často se používá i spojení 노래를 부르다 (zpívat píseň).","tv":["노래해요"]},{"id":"ko-k3-0243","w":"화장","cs":"líčení, make-up","en":"makeup","p":"n","o":"s","ex":"주연 씨, 화장 안 했어요?","exc":"Džujon, ty nejsi nalíčená?","h":"HWA-DŽANG ≈ FAJN ŽANETA: Žaneta se před zrcadlem fajn nalíčí.","m":"化 změnit + 粧 líčit se = proměnit se líčením. 화장하다 = nalíčit se. 化粧 + 室 = 화장실 (toaleta).","hada":1,"r":["hwa-化","jang-粧"]},{"id":"ko-k3-0244","w":"늦게","cs":"pozdě","en":"late","p":"o","o":"k","ex":"늦게 일어나서 화장 안 하고 왔어요.","exc":"Vstala jsem pozdě, tak jsem přišla nenalíčená. (-아서 → protože, tak; -고 → a)","h":"NŮT ≈ NUTELA: kvůli nutele přišel pozdě.","m":"Příslovce utvořené ze slovesa/přídavného jména 늦다 (mít zpoždění, být pozdní) + přípona -게. Opak 일찍 (brzy)."},{"id":"ko-k3-0245","w":"행복하다","cs":"šťastný","en":"to be happy","p":"a","o":"s","ex":"요즘 정말 바빠요. 그래도 행복해요.","exc":"V poslední době mám opravdu napilno. Přesto jsem šťastný.","h":"HENG-POK ≈ „HEJ, POHÁR!“: vyhrál jsi pohár – jsi šťastný.","m":"幸 štěstí + 福 blaho, štěstí = dvojnásobné štěstí, tedy být šťastný. Podstatné jméno je 행복 (štěstí).","r":["haeng-幸","bok-福"],"tv":["행복해요"]},{"id":"ko-k3-0246","w":"회사","cs":"firma; společnost; kancelář (v práci)","en":"company, office","p":"n","o":"s","ex":"집에서 회사까지 진짜 멀어요.","exc":"Z domova do práce je to fakt daleko. (에서 → od, z; 까지 → až do)","h":"HWE-SA ≈ VĚŠÁK: ve firmě visí tvůj kabát na věšáku.","m":"會 spolek, setkání + 社 společnost, firma = obchodní společnost, firma. Člověk pracující ve firmě je 회사원 (zaměstnanec firmy).","r":["hoe-會","sa-社"]},{"id":"ko-k3-0247","w":"힘들다","cs":"náročný; namáhavý; těžký; vyčerpávající","en":"to be hard, tiring","p":"a","o":"k","ex":"그래도 힘들지 않아요.","exc":"Přesto to není náročné. (-지 않다 → zápor)","h":"HIM-DŮL ≈ HIMÁLAJ Z DOLU: šplhat z dolu na Himálaj je vyčerpávající.","m":"Složené z 힘 (síla) + 들다 (vstupovat, stát/vyžadovat) = vyžadovat hodně síly, tedy být namáhavý nebo těžký. Nepravidelné ㄹ → 힘든 일 (náročná práce).","tv":["힘들어요"]},{"id":"ko-k3-0248","w":"기다리다","cs":"čekat; počkat","en":"to wait","p":"v","o":"k","ex":"그래도 기다려 줄 수 있어요?","exc":"Přesto na mě můžeš počkat? (-아 주다 → udělat pro někoho; -ㄹ 수 있다 → moci)","h":"KI-DA ≈ KYTARA: čekání si krátíš kytarou.","m":"Zdvořilá žádost ‚Počkejte prosím‘ je 기다려 주세요 (v hovoru často zkráceno na 기다려 줘).","tv":["기다려요"]},{"id":"ko-k3-0249","w":"끝나다","cs":"skončit; končit (samo od sebe)","en":"to end, to finish","p":"v","o":"k","ex":"일이 늦게 끝날 거예요.","exc":"Práce skončí pozdě. (이 → 1. pád; -ㄹ 거예요 → bude)","h":"KŮN-NA ≈ KONEC: film skončil.","m":"Výslovnost [끈나다]. Intranzitivní sloveso ‚skončit‘ (수업이 끝났어요 = hodina skončila). Pozor na záměnu s 끝내다 (ukončit něco – s 4. pádem)."},{"id":"ko-k3-0250","w":"여름","cs":"léto","en":"summer","p":"n","o":"k","ex":"너무 더워요. 그래도 저는 겨울보다 여름이 더 좋아요.","exc":"Je moc horko. Přesto mám raději léto než zimu. (는 → téma; 보다 → než; 이 → 1. pád)","h":"JO-RŮM ≈ „JO, RUM!“: v létě rum s ledem.","m":"Čtyři roční období: 봄 (jaro), 여름 (léto), 가을 (podzim), 겨울 (zima). Letní prázdniny jsou 여름 방학."}],"gram":{"id":"ko-k3-g12","w":"그래도","en":"But still, Nevertheless","cs":"přesto, i tak, ale stejně","vy":"Spojka 그래도 stojí na začátku věty a vyjadřuje odporovací význam ‚přesto, i tak, ale stejně‘. Připouští předchozí situaci nebo překážku, ale uvádí, že výsledek či postoj mluvčího se nemění. V rychlé hovorové řeči může znít jako [그래두], píše se ale vždy 그래도.","m":"Složenina 그렇다 (být takový) + -아도/어도 (i kdyby / přestože) = ‚i když je to tak‘. Pozor na záměnu s 그래서 (proto, a tak) a 그런데 / 근데 (ale, mimochodem).","s":[["비가 와요. 그래도 갈 거예요?","Prší. Přesto půjdeš?"],["한국어는 어려워요. 그래도 재미있어요.","Korejština je těžká. Ale stejně je zajímavá."],["어제는 비가 왔어요. 그래도 축구를 했어요.","Včera pršelo. Přesto jsme hráli fotbal."],["저도 돈이 없어요. 그래도 걱정하지 마세요.","Já taky nemám peníze. Ale i tak si nedělejte starosti."],["노래방에 가야 돼요. 그래도 노래 안 할 거예요.","Musím jít do karaoke baru. Přesto ale zpívat nebudu."],["요즘 바빠요. 그래도 한국어를 공부하고 있어요.","V poslední době mám napilno. Přesto se ale pořád učím korejsky."],["그래도요.","Ale stejně… (zdvořilý tvar)"],["주연 씨, 화장 안 했어요?","Džujon, ty nejsi nalíčená?"],["늦게 일어나서 화장 안 하고 왔어요.","Vstala jsem pozdě, takže jsem přišla nenalíčená."],["그래도 너무 예뻐요.","I tak jsi strašně hezká."],["너무 배불러요. 그래도 더 먹을 수 있어요.","Jsem strašně plný. Ale stejně zvládnu sníst ještě víc."],["요즘 정말 바빠요. 그래도 행복해요.","Poslední dobou mám fakt napilno. Přesto jsem šťastný."],["집에서 회사까지 진짜 멀어요. 그래도 힘들지 않아요.","Z domova do práce je to fakt daleko. Přesto to ale není náročné."],["일이 늦게 끝날 거예요. 그래도 기다려 줄 수 있어요?","Práce mi skončí pozdě. Počkáš na mě i tak?"],["알아요. 그래도 먹을 거예요.","Já vím. Ale stejně to sním."],["바나나 우유가 없어요? 그래도 괜찮아요.","Nemají banánové mléko? Nevadí, i tak je to v pohodě."]]}};
